import Foundation
import Intents
import UIKit

/// How a play request from an App Intent ended.
public enum SiriMediaAppIntentOutcome {
  case playing(title: String?, artist: String?)
  case notFound
  case loginRequired
  /// Siri playback is switched off in the app settings.
  case disabled
  case failed
}

/// Entry point for the App Intents in the app target (generated by
/// `plugins/ios/withSiri.js`). App Intent metadata is only extracted from the
/// app target itself, so the intents live there and hand their requests to the
/// same JavaScript bridge as the SiriKit media intents.
public enum SiriMediaAppIntentBridge {
  /// An App Intent may also have to cold start the app and React, and Siri
  /// waits longer for it than for a media intent.
  static let playTimeout: TimeInterval = 20

  /// Searches and plays `query`; without a query JavaScript resumes playback
  /// (or starts the home feed), like "Play ReactTube".
  ///
  /// - Parameters:
  ///   - mediaType: what `query` names, e.g. `.artist`; unknown means a song or video.
  ///   - itemIdentifier: an `rt:video:<id>` item Siri already resolved.
  ///   - startReactHeadless: see `SiriMediaIntentRouter.handler`.
  @MainActor
  public static func play(
    query: String?,
    mediaType: INMediaItemType = .unknown,
    artistName: String? = nil,
    albumName: String? = nil,
    itemIdentifier: String? = nil,
    startReactHeadless: @escaping @MainActor () -> UIView?
  ) async -> SiriMediaAppIntentOutcome {
    guard SiriMediaSettings.playbackEnabled else {
      SiriMediaLog.write("app intent play while Siri playback is disabled")
      return .disabled
    }
    let headless = SiriHeadlessHost.startIfNeeded(startReactHeadless)
    let payload = SiriMediaPayload.make(
      appIntent: "play",
      query: query,
      mediaType: mediaType,
      artistName: artistName,
      albumName: albumName,
      itemIdentifier: itemIdentifier,
      delivery: "handleInApp",
      headlessStart: headless
    )
    return await withCheckedContinuation { continuation in
      SiriMediaCenter.shared.enqueue(payload, timeout: playTimeout) { result, nowPlaying in
        switch result {
        case .success:
          continuation.resume(returning: .playing(title: nowPlaying?.title, artist: nowPlaying?.artist))
        case .notFound:
          continuation.resume(returning: .notFound)
        case .loginRequired:
          continuation.resume(returning: .loginRequired)
        case .failure:
          continuation.resume(returning: .failed)
        }
      }
    }
  }

  /// Opens the music search with `query`. The intent opens the app first; when
  /// Siri playback is disabled, JavaScript shows the Siri settings instead.
  @MainActor
  public static func search(query: String) {
    let payload = SiriMediaPayload.make(appIntent: "search", query: query, delivery: "continueInApp")
    SiriMediaCenter.shared.enqueue(payload, completion: nil)
  }
}
